import{_ as n,l as t,o as r,c as l,v as e,p as s,x as o,d,i as k,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Grokking 与突然泛化","description":"","frontmatter":{"title":"Grokking 与突然泛化","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grokking.md","filePath":"llm/grokking.md","lastUpdated":1789023840000}'),E={name:"llm/grokking.md"};function g(h,a,c,m,u,B){const i=t("Mermaid");return r(),l("div",null,[a[1]||(a[1]=e('<h1 id="grokking-与突然泛化" tabindex="-1">Grokking 与突然泛化 <a class="header-anchor" href="#grokking-与突然泛化" aria-label="Permalink to &quot;Grokking 与突然泛化&quot;">​</a></h1><div class="epigraph"><p>我们完全反向工程了这些网络学到的算法：用离散傅里叶变换和三角恒等式，把加法变成圆上的旋转。</p><footer>—— Nanda et al., Progress Measures for Grokking via Mechanistic Interpretability, ICLR 2023</footer></div><p>Grokking 指训练集已经拟合之后很久，测试准确率才突然从随机涨到近乎完美。Power、Burda、Edwards、Babuschkin 与 Misra 在 2022 年于小算法任务（模加法、群运算）上系统报告了这一现象：过拟合阶段的测试性能可以长期极差，然后在继续训练中「顿悟」。表面上这像能力的不连续涌现。Nanda 等人随后在模加法 Transformer 上把学到的算法拆开，定义连续的进度度量，表明顿悟发生在记忆分量被清掉的时候，泛化电路其实早就在长。本篇写现象、机制、以及它和大规模涌现的类比能走多远。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典学习曲线里，训练损失与测试损失大致同进退。Grokking 把两条曲线拉开：训练准确率很快到 100%，测试准确率在过拟合平台上停留很久，然后在几乎不变的训练损失下突然上升。Power 等人用小型 Transformer 与 MLP，在模运算、置换群等任务上复现，并观察到权重衰减、数据量、模型宽度都会移动「顿悟」所需的步数。</p><p>若只有行为曲线，解释可以是任意的：隐式正则、随机游走碰巧走到平坦区、数据被突然「理解」。要区分这些故事，需要能在测试准确率仍然很差时，就测量泛化算法是否已经出现。这正是机制解释能提供的进度度量。</p><h3 id="过拟合平台不是什么都没学" tabindex="-1">过拟合平台不是什么都没学 <a class="header-anchor" href="#过拟合平台不是什么都没学" aria-label="Permalink to &quot;过拟合平台不是什么都没学&quot;">​</a></h3><p>平台期的测试损失高，不表示内部没有结构。可能同时存在两条解：一条记忆训练集的查找表，一条真正的算法。训练损失对两者都满意；测试损失只认可后者。若记忆解的权重范数更大，权重衰减会慢慢偏向算法解。表面上的突变，来自测试度量对「记忆还是算法」的不连续敏感，而不是参数空间里的跳跃。</p><p><span class="marginnote">Power 等人的设定是小数据、可穷尽的算法表，和网页语料上的 LLM 涌现不是同一实验。把 grokking 直接叫做「大模型突然会推理的微型版」，是类比，需要额外证据。有用的移植是方法：用内部进度度量去拆开行为上的不连续。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Nanda 等人的主实验：一层或两层 Transformer 学 \\(a+b \\bmod p\\)，带权重衰减。他们发现网络把加数表示成某些频率上的正弦/余弦，再用三角积化和差实现模加，相当于在圆上旋转再读出。验证手段包括：权重与激活的傅里叶谱、在傅里叶空间做消融、以及用解析的旋转算法替换对应分量后性能几乎不变。</p><p>基于这一理解，定义两条进度度量。限制损失（restricted loss）：只保留关键频率，其余消融，看泛化电路单独的表现。排除损失（excluded loss）：只消融关键频率，看记忆通路还能否拟合训练点。两者在测试准确率突变之前就已经连续变化。</p><h3 id="训练的三个阶段" tabindex="-1">训练的三个阶段 <a class="header-anchor" href="#训练的三个阶段" aria-label="Permalink to &quot;训练的三个阶段&quot;">​</a></h3><p>主线实验被分成三阶段。记忆期：训练损失下降，排除损失下降，测试与限制损失仍高——模型在用非关键频率记表。电路形成期：限制损失开始下降，泛化机制进入权重，但记忆分量还在，测试仍差。清理期：权重衰减拆掉记忆分量，测试准确率陡升——grokking 发生在这里。突变是清理的表观，不是电路从零瞬间出现。</p><p>Liu 等人的 Omnigrok 等工作用权重范数与表示范数画相图，指出 grokking 与「表示要长到足够大、权重又被正则压住」的平衡有关。这与 Nanda 的清理故事相容：正则是把记忆解赶出赛道的力。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模加的傅里叶算法为何被找到？正弦基对循环群是自然的，梯度下降从随机初始化里放大了这些频率，因为它们能用平滑函数拟合全部加法表，而不必为每个 \\((a,b)\\) 存一项。记忆解在有限训练集上一样能把训练损失打到零，而且往往形成得更快，所以先出现。权重衰减惩罚大范数的查找表，慢变量（算法频率）后来居上。测试准确率只在记忆被拆掉后才反映算法已经就绪。</p><h3 id="进度度量相对行为度量" tabindex="-1">进度度量相对行为度量 <a class="header-anchor" href="#进度度量相对行为度量" aria-label="Permalink to &quot;进度度量相对行为度量&quot;">​</a></h3><p>进度度量的要点是：它们在行为不连续之前连续可测。这为「涌现」提供了一种拆解策略——先反向工程最终算法，再定义该算法的内部强度，最后看强度是否平滑增长。Chughtai 等人在群运算上得到类似的阶段结构。若一种涌现现象找不到任何连续内部度量，才更像真正的相变；grokking 至少在模加上不是。</p><p><span class="marginnote">关键频率是事后知道的。进度度量依赖已经反向工程的算法，不能在训练开始前当通用早停器。它解释历史，不自动预测下一次顿悟何时到来。通用预测需要不依赖最终电路的代理量，例如权重范数、表示稀疏性，这些更弱、更可迁移。</span></p><p>数据量有阈值。太少则算法解不存在或正则来不及赢；太多则一开始就更像普通学习，平台变短。Power 等人画过数据分数与 grokking 延迟的关系。工程上若只关心测试性能，更简单的办法往往是加数据或加强正则，而不是空等顿悟。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>模加上的完美反向工程，目前没有在真实语言模型的「突然会某任务」上复现到同一精度。LLM 的数据不是封闭群表，记忆与算法的边界模糊。把 grokking 当训练配方（「过拟合后再多训一万步」）在大规模上通常不划算：计算应花在数据与目标函数，而不是等待清理期。它更有价值的是概念：行为涌现可以是度量的非线性，内部可以平滑。</p><p>正则选择影响是否出现 grokking。权重衰减是 Nanda 主线；dropout 等也能诱发。没有正则时，记忆解可以长期占据，测试不升。优化器、学习率、是否用满算法表的一部分做训练，都会改阶段边界。复现必须把这些超参写全。</p><p><span class="marginnote">不要把训练曲线上任何测试延迟上升都叫 grokking。学习率调度、数据顺序、评测集污染解除，都能造成「突然变好」。Grokking 特指：训练已饱和、持续过拟合之后、在同一数据分布上泛化陡升。定义收紧，讨论才有意义。</span></p>',25)),(r(),s(p,null,{default:o(()=>[k(i,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E8%AE%B0%E5%BF%86%E6%9C%9F%3A%20%E8%AE%AD%E7%BB%83%E6%8D%9F%E5%A4%B1%E2%86%93%20%E6%B5%8B%E8%AF%95%E4%BB%8D%E5%B7%AE%22%5D%20--%3E%20C%5B%22%E7%94%B5%E8%B7%AF%E5%BD%A2%E6%88%90%3A%20%E9%99%90%E5%88%B6%E6%8D%9F%E5%A4%B1%E2%86%93%22%5D%0A%20%20C%20--%3E%20U%5B%22%E6%B8%85%E7%90%86%E6%9C%9F%3A%20%E6%9D%83%E9%87%8D%E8%A1%B0%E5%87%8F%E5%8E%BB%E6%8E%89%E8%AE%B0%E5%BF%86%22%5D%0A%20%20U%20--%3E%20G%5B%22%E6%B5%8B%E8%AF%95%E5%87%86%E7%A1%AE%E7%8E%87%E9%99%A1%E5%8D%87%20%3D%20grokking%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Grokking 是训练已拟合后测试性能延迟陡升的现象，Power 等人在小算法数据集上确立。</li><li>Nanda 等人证明模加网络学的是傅里叶旋转算法，并用限制/排除损失显示内部进度是连续的。</li><li>三阶段为记忆、电路形成、清理；行为突变发生在清理，而不是算法诞生瞬间。</li><li>权重衰减等正则把高范数记忆解挤掉，使泛化解成为测试时的唯一通路。</li><li>与 LLM 涌现可类比的是「度量非线性」，不是「小群表训练配方可直接放大」。</li><li>出处：Power et al., <em>Grokking: Generalization Beyond Overfitting on Small Algorithmic Datasets</em>, 2022；Nanda et al., ICLR 2023（arXiv:2301.05217）。</li></ul>',2))])}const f=n(E,[["render",g]]);export{A as __pageData,f as default};
